[Resource from github at repo://missingbulb/LaughCounter/sha/1774c51fdde5ab9962ef4d50f6d94cecdca66b00/contents/mac/Package.swift] // swift-tools-version:5.9
import PackageDescription

// LaughCounter — a tiny native macOS menu-bar app.
//
// It depends on NOTHING outside the OS: AppKit (menu bar + sound), AVFoundation
// (microphone), SoundAnalysis (Apple's built-in laughter classifier) and Speech
// (on-device "I just laughed" voice command) all ship with macOS. That is the
// whole point — nothing to install, nothing left behind when you delete the app.
//
// `ObjCExceptionTrap` is our own source, not a dependency: a few lines of
// Objective-C are the only way to catch an `NSException`, which Swift cannot do
// and which AVFoundation raises from `installTapOnBus` (#61).

let package = Package(
    name: "LaughCounter",
    platforms: [.macOS(.v13)],
    targets: [
        .target(
            name: "ObjCExceptionTrap",
            path: "Sources/ObjCExceptionTrap"
        ),
        .executableTarget(
            name: "LaughCounter",
            dependencies: ["ObjCExceptionTrap"],
            path: "Sources/LaughCounter"
        )
    ]
)

[Resource from github at repo://missingbulb/CrosswordChat/sha/a9b841ae4e639d07216642167a7fca854f4455fa/contents/dev/requirements/ui/render/page-to-png.js] // Rasterize a shipped extension PAGE or POPUP to PNG with headless Chromium
// (Playwright). This is the engine for surfaces satori CANNOT render — full HTML
// documents that use CSS grid, custom properties (var()), @media, emoji, or native
// form widgets (a range slider, radio buttons). help.html (grid + vars + emoji) and
// options.html (form widgets) are both such surfaces; the satori/resvg path only
// works for the inline-styled button/toolbar.
//
// Trade-off vs. satori: a real browser renders faithfully but its screenshots carry
// minor cross-environment antialiasing variance, so these goldens compare with a
// small per-case tolerance (maxDiffRatio), not diff-ratio 0. Chromium is
// pre-installed here (PLAYWRIGHT_BROWSERS_PATH); we never download it.

import { existsSync, readdirSync } from 'node:fs';
import { chromium } from 'playwright-core';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { dirname, join, resolve } from 'node:path';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..', '..', '..');

// playwright-core downloads nothing here; use the image's pre-installed Chromium (its
// build number needn't match playwright-core's pinned one). CHROMIUM_PATH overrides;
// otherwise find the `chromium-<n>/chrome-linux/chrome` under PLAYWRIGHT_BROWSERS_PATH.
function chromiumExecutable() {
  if (process.env.CHROMIUM_PATH) return process.env.CHROMIUM_PATH;
  const base = process.env.PLAYWRIGHT_BROWSERS_PATH || '/opt/pw-browsers';
  if (!existsSync(base)) return undefined;
  for (const dir of readdirSync(base).filter((d) => /^chromium-\d+$/.test(d)).sort()) {
    const p = join(base, dir, 'chrome-linux', 'chrome');
    if (existsSync(p)) return p;
  }
  return undefined; // fall back to playwright's own resolution
}

// Is a usable Chromium present? The browser cases self-skip where one isn't (e.g. a
// CI runner without it), so the satori/resvg cases still gate and CI stays green;
// the goldens remain committed and reviewable. Regenerate them where Chromium is.
export const chromiumAvailable = () => Boolean(chromiumExecutable());

/**
 * @param {string} relHtmlPath  repo-relative path to the shipped .html
 * @param {{width: number, height?: number, fullPage?: boolean,
 *          prep?: () => void, prepArg?: any}} opts
 *   width/height — viewport; fullPage — capture the whole document (for a tall page);
 *   prep — a function run in the page to set a representative state (the scripts that
 *   need the extension runtime are stripped first, so populate the form here).
 * @returns {Promise<Buffer>} PNG bytes
 */
export async function pageToPng(relHtmlPath, { width, height, fullPage = false, prep, prepArg } = {}) {
  const browser = await chromium.launch({ headless: true, executablePath: chromiumExecutable() });
  try {
    const page = await browser.newPage({ viewport: { width, height: height ?? 720 }, deviceScaleFactor: 1 });
    await page.goto(pathToFileURL(join(ROOT, relHtmlPath)).href, { waitUntil: 'load' });
    // Drop scripts that need chrome.* (they'd throw and populate nothing); the case's
    // prep sets the state a user would see instead.
    await page.evaluate(() => { for (const s of document.querySelectorAll('script')) s.remove(); });
    if (prep) await page.evaluate(prep, prepArg);
    await page.evaluate(() => (document.fonts ? document.fonts.ready : null));
    return await page.screenshot({ fullPage });
  } finally {
    await browser.close();
  }
}

/**
 * Rasterize a self-contained HTML string (no navigation, no scripts). For an in-page
 * surface that the extension INJECTS rather than serves as a page — e.g. the Settings
 * modal, whose shipped CSS + markup strings the case composes so the golden tracks the
 * real module. NYT's webfonts aren't present here, so the modal's fallback fonts render.
 * @param {string} html  a full document body's worth of HTML (styles inline or in <style>)
 * @param {{width: number, height?: number}} opts
 * @returns {Promise<Buffer>} PNG bytes
 */
export async function contentToPng(html, { width, height } = {}) {
  const browser = await chromium.launch({ headless: true, executablePath: chromiumExecutable() });
  try {
    const page = await browser.newPage({ viewport: { width, height: height ?? 720 }, deviceScaleFactor: 1 });
    await page.setContent(`<!doctype html><style>html,body{margin:0}</style>${html}`, { waitUntil: 'load' });
    await page.evaluate(() => (document.fonts ? document.fonts.ready : null));
    return await page.screenshot();
  } finally {
    await browser.close();
  }
}

[Resource from github at repo://missingbulb/EdFringeNow/sha/251d5562d54c7c3fcc990e901e18d282e766efa4/contents/product/requirements/shared/harness/browser.js] // The requirements harness's browser: pinned Playwright Chromium, a hermetic
// fake origin served from disk, and every nondeterministic input replaced —
// clock, location, randomness, network (fonts, Leaflet, map tiles, geocoding,
// live data). Every UI case (screen and behavior kinds alike) gets its page
// from here, so "deterministic" is decided once, not per case.
//
// The page is served from a FAKE origin (http://edfringenow.req/), fulfilled
// entirely from the repo working tree + committed fixtures via route
// interception — no HTTP server process, no port, nothing off-disk. Any request
// the routing table doesn't recognise is aborted, so a new external dependency
// in the product breaks the suite loudly instead of adding hidden network.
"use strict";

const fs = require("node:fs");
const os = require("node:os");
const path = require("node:path");
const { execSync } = require("node:child_process");
const { pathToFileURL } = require("node:url");

const REPO_ROOT = path.join(__dirname, "..", "..", "..", "..");
const VENDOR_DIR = path.join(__dirname, "vendor");
const FIXTURES_DIR = path.join(__dirname, "..", "fixtures");
const { REFERENCE_NOW_UTC_MS, TIMEZONE, LOCALE, GEOLOCATION } = require("../reference-now");

// Rendering is only comparable against the committed goldens when the exact
// same Chromium rasterises it. This is the Playwright whose vendored browser
// the goldens were rendered with; the runner refuses to compare with any other.
const PINNED_PLAYWRIGHT = "1.56.1";

// https, not http: geolocation only exists on secure origins. Routes are
// fulfilled before any real connection, so no certificate is involved.
const ORIGIN = "https://edfringenow.req";

// The two committed viewports. A case says `viewport: "desktop"`; everything
// else about the screen (DPR 1, no touch) is fixed here.
const VIEWPORTS = {
  mobile: { width: 390, height: 844 },
  desktop: { width: 1280, height: 900 },
};

const MIME = {
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".mjs": "text/javascript; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".json": "application/json; charset=utf-8",
  ".png": "image/png",
  ".svg": "image/svg+xml",
  ".webp": "image/webp",
  ".ico": "image/x-icon",
  ".woff2": "font/woff2",
  ".csv": "text/csv; charset=utf-8",
  ".txt": "text/plain; charset=utf-8",
};

// Playwright resolves differently per environment: CI installs it into
// node_modules (a plain import), the Claude sandbox ships it globally beside a
// pre-provisioned browser. Try the local install first, then the global build
// by its ESM entry (the CJS index.js yields undefined named exports).
async function loadPlaywright() {
  try {
    return await import("playwright");
  } catch {
    /* no local install — fall through to the global build */
  }
  const guesses = ["/opt/node22/lib/node_modules/playwright/index.mjs"];
  try {
    guesses.push(path.join(execSync("npm root -g", { encoding: "utf8" }).trim(), "playwright", "index.mjs"));
  } catch {
    /* npm unavailable — the hardcoded guess still stands */
  }
  for (const g of guesses) {
    if (fs.existsSync(g)) return import(pathToFileURL(g).href);
  }
  throw new Error(
    "Playwright not found. Install the pinned version locally: npm i --no-save playwright@" +
      PINNED_PLAYWRIGHT +
      " && npx playwright install chromium"
  );
}

function playwrightVersion() {
  const candidates = [
    path.join(REPO_ROOT, "node_modules", "playwright", "package.json"),
    "/opt/node22/lib/node_modules/playwright/package.json",
  ];
  for (const c of candidates) {
    if (fs.existsSync(c)) return JSON.parse(fs.readFileSync(c, "utf8")).version;
  }
  return null;
}

// Deterministic Math.random for the page: mulberry32, fixed seed. Runs before
// any page script.
const SEEDED_RANDOM = `
  (() => {
    let s = 0xedf12026;
    Math.random = function () {
      s |= 0; s = (s + 0x6d2b79f5) | 0;
      let t = Math.imul(s ^ (s >>> 15), 1 | s);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  })();
`;

// Freeze every visual in flight: CSS animations/transitions land on their end
// state, the text caret never blinks, smooth scrolling is instant. Injected at
// document start so nothing renders un-frozen.
const FREEZE_CSS = `
  *, *::before, *::after {
    animation-duration: 0s !important;
    animation-delay: 0s !important;
    transition-duration: 0s !important;
    transition-delay: 0s !important;
    caret-color: transparent !important;
    scroll-behavior: auto !important;
  }
`;

function fulfillFile(route, filePath, status = 200) {
  const ext = path.extname(filePath).toLowerCase();
  return route.fulfill({
    status,
    contentType: MIME[ext] || "application/octet-stream",
    body: fs.readFileSync(filePath),
  });
}

// The routing table: URL → bytes, worked out once for the whole suite.
//   - our fake origin: fixtures override, then vendor, then the repo tree;
//   - Google Fonts CSS + unpkg Leaflet/markercluster: the committed vendor copies;
//   - OSM tiles: one committed fixture tile, whatever the coordinates;
//   - the geocoder: the committed fixture response (cases exercise "found");
//   - anything else: aborted.
async function routeAll(context, { dataDir, failData }) {
  await context.route("**/*", (route) => {
    const url = new URL(route.request().url());
    const { hostname, pathname } = url;

    // Simulated outage: a case may declare URL substrings that must fail, to
    // drive the product's error states (a dead geocoder, a failed catalogue).
    if (failData && failData.some((s) => url.href.includes(s))) {
      return route.abort("failed");
    }

    // Vendored assets, on ANY host: the fonts CSS is served from the Google
    // Fonts URL, so its url(/__vendor/…) references resolve against that host.
    if (pathname.startsWith("/__vendor/")) {
      const v = path.join(VENDOR_DIR, pathname.slice("/__vendor/".length).replace("fonts/", "fonts" + path.sep));
      if (fs.existsSync(v)) return fulfillFile(route, v);
      return route.abort();
    }

    if (`${url.protocol}//${hostname}` === ORIGIN) {
      const rel = decodeURIComponent(pathname.replace(/^\/+/, "")) || "index.html";
      const withIndex = rel.endsWith("/") || rel === "" ? `${rel}index.html` : rel;
      // The version the footer/debug pill shows must not drift with releases.
      // (Stored as .fixture so no stray package.json lands in the tree.)
      if (withIndex === "package.json") {
        return route.fulfill({
          contentType: MIME[".json"],
          body: fs.readFileSync(path.join(FIXTURES_DIR, "package.json.fixture")),
        });
      }
      // Live data is replaced wholesale by the committed fixture snapshot.
      if (withIndex.startsWith("data/")) {
        const fixture = path.join(dataDir, withIndex.slice("data/".length));
        if (fs.existsSync(fixture)) return fulfillFile(route, fixture);
        return route.fulfill({ status: 404, contentType: "text/plain", body: "no fixture" });
      }
      const onDisk = path.join(REPO_ROOT, withIndex);
      if (fs.existsSync(onDisk) && fs.statSync(onDisk).isFile()) return fulfillFile(route, onDisk);
      const asDir = path.join(REPO_ROOT, withIndex, "index.html");
      if (fs.existsSync(asDir)) return fulfillFile(route, asDir);
      return route.fulfill({ status: 404, contentType: "text/plain", body: "not found" });
    }

    if (hostname === "fonts.googleapis.com") {
      return fulfillFile(route, path.join(VENDOR_DIR, "fonts", "fonts.css"));
    }
    if (hostname === "unpkg.com") {
      if (pathname.includes("/dist/images/")) {
        const img = path.join(VENDOR_DIR, "leaflet", "images", path.basename(pathname));
        if (fs.existsSync(img)) return fulfillFile(route, img);
      }
      const known = {
        "leaflet.css": "leaflet.css",
        "leaflet.js": "leaflet.js",
        "MarkerCluster.css": "MarkerCluster.css",
        "leaflet.markercluster.js": "leaflet.markercluster.js",
      }[path.basename(pathname)];
      if (known) return fulfillFile(route, path.join(VENDOR_DIR, "leaflet", known));
      return route.abort();
    }
    if (hostname.endsWith("tile.openstreetmap.org")) {
      return fulfillFile(route, path.join(FIXTURES_DIR, "tile.png"));
    }
    if (hostname === "photon.komoot.io" || hostname === "nominatim.openstreetmap.org") {
      return fulfillFile(route, path.join(FIXTURES_DIR, "geocode.json"));
    }
    return route.abort();
  });
}

// ------------------------------------------------------------- font jail --
// The web fonts are vendored, but they are not the only fonts on the page: any
// character they don't carry — an emoji, an arrow, a Cyrillic show title — is
// drawn by whatever the *machine* has installed. That made the goldens a
// record of the renderer's font set, and CI's set is not the sandbox's: the
// walk-time line ("🚶 5 min · £16") measured a different width there and
// wrapped, making every card one line taller.
//
// So the harness gives Chromium its own fontconfig world: a generated config
// whose only font directory is `vendor/systemfonts/`, with the generic
// families aliased into it. Nothing installed on the host can reach the page.
const SYSTEM_FONTS_DIR = path.join(VENDOR_DIR, "systemfonts");

function fontconfigFile() {
  const dir = path.join(os.tmpdir(), "edfringe-req-fontconfig");
  const cache = path.join(dir, "cache");
  fs.mkdirSync(cache, { recursive: true });
  const alias = (from, to) =>
    `  <alias binding="strong"><family>${from}</family><prefer><family>${to}</family></prefer></alias>`;
  const conf = `<?xml version="1.0"?>
<!DOCTYPE fontconfig SYSTEM "urn:fontconfig:fonts.dtd">
<fontconfig>
  <dir>${SYSTEM_FONTS_DIR}</dir>
  <cachedir>${cache}</cachedir>
${[
  alias("sans-serif", "DejaVu Sans"),
  alias("serif", "DejaVu Sans"),
  alias("monospace", "DejaVu Sans"),
  alias("system-ui", "DejaVu Sans"),
  alias("emoji", "Noto Color Emoji"),
  // The product's metric-matched fallback faces are `src: local("Arial")`.
  alias("Arial", "Liberation Sans"),
  alias("Helvetica", "Liberation Sans"),
].join("\n")}
</fontconfig>
`;
  const file = path.join(dir, "fonts.conf");
  fs.writeFileSync(file, conf);
  return file;
}

let browserPromise = null;

async function launchBrowser() {
  if (!browserPromise) {
    browserPromise = (async () => {
      const version = playwrightVersion();
      if (version && version !== PINNED_PLAYWRIGHT) {
        throw new Error(
          `Playwright ${version} found, but the goldens are rendered with ${PINNED_PLAYWRIGHT}. ` +
            "Rendering with a different Chromium makes every pixel comparison meaningless — install the pinned version."
        );
      }
      const { chromium } = await loadPlaywright();
      return chromium.launch({
        env: { ...process.env, FONTCONFIG_FILE: fontconfigFile() },
        args: [
          "--font-render-hinting=none",
          "--force-color-profile=srgb",
          "--disable-lcd-text",
          "--hide-scrollbars",
          // Shadow/blur rasterisation varies run-to-run without these: partial
          // raster reuses tiles whose seams land in blur corners.
          "--disable-partial-raster",
          "--disable-skia-runtime-opts",
          "--disable-gpu",
        ],
      });
    })();
  }
  return browserPromise;
}

async function closeBrowser() {
  if (browserPromise) {
    const b = await browserPromise;
    await b.close();
    browserPromise = null;
  }
}

/**
 * A fresh, fully-faked page for one case.
 * opts:
 *   viewport   "mobile" (default) | "desktop"
 *   dataDir    fixture data root (defaults to the committed snapshot)
 *   geolocation  override the fixed fake location, or null for "denied"
 *   localStorage {key: value} seeded on the fake origin before any page script
 *   nowUtcMs   override the pinned instant (rarely; the reference time is shared)
 */
async function newPage(opts = {}) {
  const browser = await launchBrowser();
  const geolocation = opts.geolocation === undefined ? GEOLOCATION : opts.geolocation;
  const context = await browser.newContext({
    viewport: VIEWPORTS[opts.viewport || "mobile"],
    deviceScaleFactor: 1,
    locale: LOCALE,
    // The device's zone. Overridable so a case can prove the product reads
    // Edinburgh's clock rather than the device's — a context's zone is fixed at
    // creation, so showing two zones means two pages.
    timezoneId: opts.timezone || TIMEZONE,
    ...(geolocation
      ? { geolocation, permissions: ["geolocation"] }
      : { permissions: [] }),
  });
  await routeAll(context, {
    dataDir: opts.dataDir || path.join(FIXTURES_DIR, "data"),
    failData: opts.failData,
  });

  const page = await context.newPage();
  const now = opts.nowUtcMs || REFERENCE_NOW_UTC_MS;
  if (opts.advanceableClock) {
    // Time still stands still, but the page's timers exist and can be wound
    // forward deliberately (page.clock.fastForward) — how a case proves
    // something the passage of time is supposed to change.
    await page.clock.install({ time: now });
    await page.clock.pauseAt(now);
  } else {
    await page.clock.setFixedTime(now);
  }
  await page.addInitScript(SEEDED_RANDOM);
  // The CSS freeze can't stop Web Animations API animations (the planner's
  // FLIP board diff) — stub element.animate so every WAAPI animation lands on
  // its end state instantly.
  await page.addInitScript(`
    Element.prototype.animate = function () {
      const anim = {
        finished: Promise.resolve(),
        onfinish: null,
        cancel() {}, finish() {}, play() {}, pause() {}, reverse() {},
        addEventListener(type, fn) { if (type === "finish") setTimeout(fn, 0); },
        removeEventListener() {},
      };
      setTimeout(() => { if (typeof anim.onfinish === "function") anim.onfinish(); }, 0);
      return anim;
    };
  `);
  await page.addInitScript(
    `document.addEventListener("DOMContentLoaded", () => {
       const s = document.createElement("style");
       s.textContent = ${JSON.stringify(FREEZE_CSS)};
       document.head.appendChild(s);
     });`
  );
  if (opts.localStorage) {
    await page.addInitScript(
      `for (const [k, v] of Object.entries(${JSON.stringify(opts.localStorage)})) localStorage.setItem(k, v);`
    );
  }
  return { page, context, origin: ORIGIN };
}

module.exports = { newPage, closeBrowser, launchBrowser, ORIGIN, VIEWPORTS, PINNED_PLAYWRIGHT };

[Resource from github at repo://missingbulb/CrosswordChat/sha/a9b841ae4e639d07216642167a7fca854f4455fa/contents/dev/build/make-store-assets.mjs] #!/usr/bin/env node
// Generate all Chrome Web Store graphics from code — icons, screenshots, promo tiles.
// Everything is drawn as inline SVG/HTML and rasterized with headless Chromium, so the
// assets are reproducible: edit this file, re-run, commit the PNGs.
//
//   node dev/build/make-store-assets.mjs
//
// Outputs:
//   extension/icons/icon-{16,32,48,128}.png              — manifest icons (transparent corners)
//   extension/icons/icon-{16,32,48,128}-gray.png         — unsupported-tab variant (REQ-LIFE-013)
//   dev/build/release/store_artifacts/screenshot-{1,2}-1280x800.png — store screenshots
//   dev/build/release/store_artifacts/promo-small-440x280.png      — small promo tile
//   dev/build/release/store_artifacts/promo-marquee-1400x560.png   — marquee promo tile
//
// Chromium: uses Playwright's managed browser (PLAYWRIGHT_BROWSERS_PATH) when present;
// set CHROME_BIN to point at any Chromium/Chrome binary otherwise.

import { chromium } from 'playwright-core';
import { mkdirSync, readdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { GOLD, INK, brandIconSvg } from '../../extension/src/shared/brand-icon.js';

const ROOT = new URL('../..', import.meta.url).pathname;
const ICONS = join(ROOT, 'extension/icons');
const STORE = join(ROOT, 'dev/build/release/store_artifacts');
mkdirSync(ICONS, { recursive: true });
mkdirSync(STORE, { recursive: true });

// ---------------------------------------------------------------- palette ---
// GOLD (crossword gold) and INK (near-black) come from the shared brand module.

const GOLD_SOFT = '#F8DE8D';
const PAPER = '#FAF6EC';      // warm off-white page
const CARD = '#FFFFFF';
const SERIF = "'Bitstream Charter', 'Liberation Serif', Georgia, serif";
const SANS = "'Liberation Sans', Arial, sans-serif";

// ------------------------------------------------------------------- icon ---
// A speech bubble that is itself a crossword grid: 3×2 cells, one black square.
// Geometry lives in extension/src/shared/brand-icon.js — one source for the store
// assets, the action icons, AND the in-page toolbar button (REQ-LIFE-012).

const iconSvg = brandIconSvg({ bg: GOLD, ink: INK, bubble: '#FFFFFF' });
// Unsupported-tab variant (REQ-LIFE-013): the same mark, drained of color, so the
// action icon itself says "CrosswordChat has nothing to do here".
const iconSvgGray = brandIconSvg({ bg: '#D9D9D9', ink: '#7C7C7C', bubble: '#F3F3F3' });

const iconPage = (svg, px) => `<!doctype html><html><head><style>
  html,body{margin:0;padding:0;background:transparent}
  svg{display:block;width:${px}px;height:${px}px}
</style></head><body>${svg}</body></html>`;

// ------------------------------------------------------- shared page bits ---

const baseCss = `
  *{margin:0;padding:0;box-sizing:border-box}
  html,body{width:100%;height:100%;overflow:hidden}
  body{background:${PAPER};font-family:${SANS};color:${INK};
       display:flex;flex-direction:column}
  .serif{font-family:${SERIF}}
`;

const brandRow = (size) => `
  <div style="display:flex;align-items:center;gap:${size * 0.35}px">
    <div style="width:${size}px;height:${size}px;flex:none">${iconSvg}</div>
    <div class="serif" style="font-size:${size * 0.62}px;font-weight:bold">CrosswordChat</div>
  </div>`;

// A decorative mini crossword grid. `cells` is an array of row strings:
// '#' = black square, letter = filled, '.' = empty, lowercase = active (gold) cell.
function gridHtml(cells, cellPx) {
  const rows = cells.map((row) => [...row].map((ch) => {
    const black = ch === '#';
    const active = ch >= 'a' && ch <= 'z';
    const letter = ch === '.' || black ? '' : ch.toUpperCase();
    return `<div style="width:${cellPx}px;height:${cellPx}px;border:1.5px solid ${INK};
      margin:-0.75px;display:flex;align-items:center;justify-content:center;
      background:${black ? INK : active ? GOLD_SOFT : CARD};
      font-family:${SERIF};font-weight:bold;font-size:${cellPx * 0.58}px">${letter}</div>`;
  }).join('')).join('</div><div style="display:flex">');
  return `<div style="display:inline-block;border:3px solid ${INK};background:${CARD}">
    <div style="display:flex">${rows}</div></div>`;
}

function bubble(text, { user = false, size = 26 } = {}) {
  return `<div style="align-self:${user ? 'flex-end' : 'flex-start'};max-width:82%;
    background:${user ? GOLD : CARD};border:2px solid ${INK};border-radius:16px;
    border-${user ? 'bottom-right' : 'bottom-left'}-radius:4px;
    padding:${size * 0.55}px ${size * 0.8}px;font-size:${size}px;line-height:1.35;
    box-shadow:3px 3px 0 rgba(25,25,25,.12)">
    <span style="font-size:${size * 0.85}px">${user ? '🎤' : '🔊'}</span>&nbsp; ${text}</div>`;
}

// ---------------------------------------------------- in-page toolbar mock ---
// The NYT puzzle toolbar as the solver sees it, with the CrosswordChat button sitting
// right of the pencil — the "here's where you turn it on" visual (REQ-LIFE-012). The
// button wears the brand icon itself, exactly like the real one
// (extension/src/page-adapter/session-button.js).

const lineIcon = (inner, size = 27) => `<svg viewBox="0 0 24 24" width="${size}" height="${size}"
  fill="none" stroke="${INK}" stroke-width="1.8" stroke-linecap="round"
  stroke-linejoin="round">${inner}</svg>`;

const PENCIL_ICON = lineIcon('<path d="M17 3a2.8 2.8 0 0 1 4 4L7.5 20.5 3 21.5 4 17z"/>');
const CHAT_BUTTON = brandIconSvg({ bg: GOLD, ink: INK, bubble: '#FFFFFF', size: 34 });

const toolbarMock = `
  <div style="background:${CARD};border:2.5px solid ${INK};border-radius:16px;
              box-shadow:4px 4px 0 rgba(25,25,25,.12);padding:15px 30px;
              display:flex;align-items:center;gap:30px">
    <div style="font-size:21px;color:#3d3d3d;font-variant-numeric:tabular-nums">⏱&nbsp;27:31</div>
    <div style="flex:1"></div>
    ${['Rebus', 'Clear', 'Reveal', 'Check'].map((label) =>
      `<div style="font-size:20px">${label}</div>`).join('')}
    <div style="width:27px;height:27px;border:2px solid ${INK};border-radius:50%;flex:none;
                display:flex;align-items:center;justify-content:center;
