4	// Leaflet pack: portable runtime gotchas for the Leaflet web-mapping library
5	// (map init, tile layers, markers/divIcons, and CDN-loaded plugins like
6	// Leaflet.markercluster). Most are runtime behaviours with no repo-state
7	// signature and stay prose; the CDN wiring of the assets themselves is written
8	// into the HTML, and a tile layer's attribution is written into its own options
9	// object, so those convert. Fingerprinted by an actual Leaflet reference: a
10	// CDN asset (leaflet@ / leaflet.js / leaflet.css) in HTML, or a Leaflet API call
11	// site (L.map( / L.tileLayer( / L.markerClusterGroup() ) in source. The marker
12	// only *suspects* the pack; declaring it is the project's call, like every pack.
13	
14	const LEAFLET_ASSET = /\bleaflet(\.js|\.css|@[\d.]|[-/]dist)/i;
15	const LEAFLET_API = /\bL\.(map|tileLayer|markerClusterGroup)\s*\(/;
16	const SOURCE = /\.(html?|mjs|cjs|jsx?|tsx?)$/;
17	
18	export default {
19	  id: 'leaflet',
20	  version: 1,
21	  minEngineVersion: 1,
22	  ruleRoutingGuidance: {
23	    belongs: 'map rendering with the Leaflet library — map init options, tile layers, markers and divIcons, CDN plugin pinning',
24	    excludes: 'generic HTML markup rules — that is html; non-map dependency policy belongs to node',
25	  },
26	  badge: 'badge.svg',
27	  marker: 'a Leaflet reference (CDN asset, or an L.map/L.tileLayer/L.markerClusterGroup call) in HTML/JS source',
28	  detect: (ctx) =>
29	    ctx.tracked.some((f) => {
30	      if (!SOURCE.test(f)) return false;
31	      const text = ctx.read(f);
32	      return text !== null && (LEAFLET_ASSET.test(text) || LEAFLET_API.test(text));
33	    }),
34	  prose: 'RULES.md',
35	  worldRules: [assetIntegrity, tileAttribution],
36	};
