node -e "
const DRIVER_MODULE = /['\"](playwright(?:-core)?|puppeteer(?:-core)?)['\"]/;
const LAUNCH_CALL = /\b(?:chromium|firefox|webkit|puppeteer)\.launch\s*\(/;
const samples = {
  'CrosswordChat page-to-png.js': \"import { chromium } from 'playwright-core';\",
  'CrosswordChat launch call': 'const browser = await chromium.launch({ headless: true, executablePath: chromiumExecutable() });',
  'EdFringeNow dynamic import': 'return await import(\"playwright\");',
  'EdFringeNow launch call': 'return chromium.launch({ env: { ...process.env } });',
  'puppeteer require': \"const puppeteer = require('puppeteer');\",
  'NEGATIVE plain prose': 'we should test this in a browser someday',
  'NEGATIVE leaflet': \"const map = L.map(el, { scrollWheelZoom: false });\",
};
for (const [k, v] of Object.entries(samples)) console.log((DRIVER_MODULE.test(v)||LAUNCH_CALL.test(v)) ? 'MATCH  ' : 'no     ', k);
"

